def check_divisibility(n):
    if n < 0:
        return False

    # Divisor D(n) = n^3 + 4n^2 + 6n + 4
    divisor = n**3 + 4*n**2 + 6*n + 4

    # Dividend N(n) = 20^(n+1)
    dividend = 20**(n + 1)

    if divisor == 0:
        # Should not happen for n >= 0
        return False 

    if dividend % divisor == 0:
        return True
    else:
        return False

solutions = []
# Test up to n=15 for initial data collection
for n in range(16):
    if check_divisibility(n):
        solutions.append(n)
    print(f"n={n}: Solution? {check_divisibility(n)}")

print(f"\nSolutions found up to n=15: {solutions}")

def check_diophantine(a):
    """Checks if 2^(2a-1) - 2^a + 1 is a power of 5."""
    if a < 1:
        return None, False

    target = (2**(2*a - 1)) - (2**a) + 1

    if target <= 0:
        return None, False

    # Check if target is a power of 5
    m = 0
    temp = target
    while temp > 1 and temp % 5 == 0:
        temp //= 5
        m += 1

    if temp == 1:
        return target, True
    else:
        return target, False

# Test values of a starting from 1 up to 15
results = {}
for a in range(1, 16):
    target, is_power_of_5 = check_diophantine(a)
    if is_power_of_5:
        results[a] = target

print(f"Solutions found for a up to 15: {results}")

import math

def check_solution(y):
    N_squared = 2 * (5**y) - 1
    N = math.isqrt(N_squared)
    if N * N == N_squared:
        return N
    return None

solutions = {}
# Check for y up to 15 to find solutions for N up to ~250,000
for y in range(0, 16):
    N = check_solution(y)
    if N is not None:
        solutions[y] = N
print("Solutions (y, N):", solutions)
